"""Render verification ledger without turning missing results into PASS."""
import json
from pathlib import Path
root=Path(__file__).resolve().parent
results=json.loads((root/'evidence/current-main/RESULTS.json').read_text())
lines=['# Новые проверки A1 5–8','', 'author: Codex; reviewed_by: automated reproducible checks; verification_status: technical_review; date: 2026-10-25', 'source_notes: actual local process exit codes, full logs under evidence/current-main.', '', 'Baseline 5826785ee3f665fac765783ba9a95a5dd3b52655, явная изолированная временная SQLite. Production не использовалась.', '', '| Проверка | Команда | Результат | Секунды |', '|---|---|---|---|']
for r in results:
    lines.append('| '+r['name']+' | `'+ ' '.join(r['command']).replace('|','\\|') +'` | '+r['status']+' (exit '+str(r['exit_code'])+') | '+str(r['seconds'])+' |')
lines.extend(['', 'Полные результаты: [RESULTS.json](evidence/current-main/RESULTS.json). Каждый лог назван по имени проверки.', '', '## Ограничения', '', '- PostgreSQL: BLOCKED — нет postgres/initdb/Docker. SQLite PASS не заменяет проверку другой СУБД.', '- Desktop/390 px, клавиатура/reduced-motion: BLOCKED — нет браузера; попытка установки Chromium завершилась повреждённым ZIP. HTTP-проверка и разбор HTML не являются визуальной приёмкой.', '- Настоящая озвучка: BLOCKED — прослушивание не проводилось. audio-readiness с exit 0 — диагностический отчёт, не аудиоприёмка.', '- Coverage workflow: BLOCKED — pytest-cov не входит в frozen lockfile; зависимости не обновлялись ради этого прогона.', '- Пилот с людьми и повторная содержательная приёмка: BLOCKED — не проводились.', '', '## Разделение доказательств', '', 'targeted-before: исходные 18 методов, 66 failures; support-before: 3 метода, 5 failures; JS before: 1 failure в 2 тестах. Это ожидаемые воспроизведения на исходнике fb79cd7. SHA тестов зафиксированы; целевые материалы 5–8 не менялись в merge117.', '', 'Каталоги final/final-complete/verified и ранние targeted-логи — промежуточные версии. Остановленные прогоны не считаются PASS. Последняя последовательность current-main относится к main после слияния117; отдельные последние уточнения R17 при наличии отмечаются отдельно.', '', 'Старые журналы GitHub Actions не использованы для присвоения PASS новым правкам. Новый CI после публикации PR должен рассматриваться отдельно.'])
(root/'CHECKS.md').write_text('\n'.join(lines)+'\n')
